/* ============================== THEATRES ==================================
   Everything beyond 1943-45 Europe: the Blitzkrieg armies of 1939-40 and the
   armies they fought, the Pacific and China, and the war at sea. New terrain,
   unit roles (cavalry, U-boats, escorts, capital ships, carriers, torpedo
   bombers, merchantmen), nations, generals and admirals. */

/* ---------- terrain ---------- */
Object.assign(TER, {
  jungle:{n:'Jungle', def:3, mv:{foot:2, boot:2, tread:3, air:1, amphib:3}, mm:'#24502a', info:'Rain forest and secondary growth. Vehicles crawl; infantry infiltrate. The Japanese went round British roadblocks through it all the way down Malaya.'},
  paddy: {n:'Rice paddies', def:0, mv:{foot:2, boot:2, tread:3, air:1, amphib:2}, mm:'#7aa86a', info:'Flooded fields behind low bunds. No cover, and wheels sink in.'},
  reef:  {n:'Coral reef', def:0, mv:{foot:2, boot:2, air:1, amphib:1}, mm:'#62b4b0', info:'At Tarawa the tide was low: Higgins boats grounded on the reef and Marines waded 500 yards under fire. Amtracs crawl over it.'},
  palm:  {n:'Palm grove', def:2, mv:{foot:1, boot:1, tread:2, tire:2, air:1, amphib:2}, mm:'#4a7a34', info:'Coconut and rubber plantations: shade, some cover, and roads between the rows.'},
  loess: {n:'Loess hills', def:2, mv:{foot:1, boot:1, tread:2, tire:3, air:1, amphib:2}, mm:'#b89a62', info:'The terraced yellow earth of north China, cut by gullies.'},
});
Object.assign(MAPCH, {J:['jungle'], y:['paddy'], R:['reef'], L:['palm'], l:['loess']});
for (const t of ['jungle', 'palm', 'loess']) HIDES.add(t);
const _inGroup = inGroup;
inGroup = function (d, g, terrain) {             // jungles, groves and loess count as cover
  if (g === 'cover' && ['jungle', 'palm', 'loess'].includes(terrain)) return true;
  if (g === 'naval') return !!d.sea;
  if (g === 'subs') return !!d.sub;
  return _inGroup(d, g, terrain);
};

/* ---------- unit roles ---------- */
